window.ScripturaLexicons.BDAG_PART_0340 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-01\" data-source=\"BDAG\" data-search=\"συμφθείρω verbo decompor-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφθείρω</td><td>verbo</td><td>decompor-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-02\" data-source=\"BDAG\" data-search=\"συμφορά, ᾶς, ἡ substantivo feminino infortúnio; calamidade; desastre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφορά, ᾶς, ἡ</td><td>substantivo feminino</td><td>infortúnio; calamidade; desastre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-03\" data-source=\"BDAG\" data-search=\"σύμφορος, ον adjetivo benéfico; vantajoso; proveitoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύμφορος, ον</td><td>adjetivo</td><td>benéfico; vantajoso; proveitoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-04\" data-source=\"BDAG\" data-search=\"συμφορτίζω verbo sobrecarregar juntamente com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφορτίζω</td><td>verbo</td><td>sobrecarregar juntamente com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-05\" data-source=\"BDAG\" data-search=\"συμφύγιον, ου, τό substantivo neutro refúgio; abrigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφύγιον, ου, τό</td><td>substantivo neutro</td><td>refúgio; abrigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-06\" data-source=\"BDAG\" data-search=\"συμφυλέτης, ου, ὁ substantivo masculino compatriota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφυλέτης, ου, ὁ</td><td>substantivo masculino</td><td>compatriota</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-07\" data-source=\"BDAG\" data-search=\"συμφυρμός, οῦ, ὁ substantivo masculino relação sexual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφυρμός, οῦ, ὁ</td><td>substantivo masculino</td><td>relação sexual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-08\" data-source=\"BDAG\" data-search=\"σύμφυτος, ον adjetivo identificado com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύμφυτος, ον</td><td>adjetivo</td><td>identificado com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-09\" data-source=\"BDAG\" data-search=\"συμφύω verbo crescer juntamente com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφύω</td><td>verbo</td><td>crescer juntamente com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-10\" data-source=\"BDAG\" data-search=\"συμφωνέω verbo corresponder; concordar; chegar a um acordo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφωνέω</td><td>verbo</td><td>corresponder; concordar; chegar a um acordo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-11\" data-source=\"BDAG\" data-search=\"συμφώνησις, εως, ἡ substantivo feminino acordo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφώνησις, εως, ἡ</td><td>substantivo feminino</td><td>acordo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-12\" data-source=\"BDAG\" data-search=\"συμφωνία, ας, ἡ substantivo feminino música; grupo musical; instrumento de sopro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμφωνία, ας, ἡ</td><td>substantivo feminino</td><td>música; grupo musical; instrumento de sopro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-13\" data-source=\"BDAG\" data-search=\"σύμφωνος, ον adjetivo harmonioso; concordante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύμφωνος, ον</td><td>adjetivo</td><td>harmonioso; concordante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-14\" data-source=\"BDAG\" data-search=\"συμψέλιον, ου, τό substantivo neutro banco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμψέλιον, ου, τό</td><td>substantivo neutro</td><td>banco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-15\" data-source=\"BDAG\" data-search=\"συμψηφίζω verbo somar; computar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμψηφίζω</td><td>verbo</td><td>somar; computar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-16\" data-source=\"BDAG\" data-search=\"σύμψυχος, ον adjetivo harmonioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύμψυχος, ον</td><td>adjetivo</td><td>harmonioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-17\" data-source=\"BDAG\" data-search=\"σύν preposição com; juntamente com; além de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύν</td><td>preposição</td><td>com; juntamente com; além de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-18\" data-source=\"BDAG\" data-search=\"συνάγω verbo reunir; recolher; reconciliar; acolher; avançar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συνάγω</td><td>verbo</td><td>reunir; recolher; reconciliar; acolher; avançar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-19\" data-source=\"BDAG\" data-search=\"συναγωγή, ῆς, ἡ substantivo feminino lugar de reunião; sinagoga; congregação; bando BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συναγωγή, ῆς, ἡ</td><td>substantivo feminino</td><td>lugar de reunião; sinagoga; congregação; bando</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0340-20\" data-source=\"BDAG\" data-search=\"συναγωνίζομαι verbo lutar juntamente com; ajudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συναγωνίζομαι</td><td>verbo</td><td>lutar juntamente com; ajudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0340-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφθείρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφθείρω</span> (Eur., Aristot., Polyb., Philo) 2.º aoristo, particípio neutro plural <span class=\"greek\">συμφθαρέντα</span> decompor-se, de grãos de trigo <span class=\"greek\">ὅτι</span> … <span class=\"greek\">συμφθαρέντα</span> <span class=\"greek\">κάτω</span> <span class=\"greek\">ἠγέρθη</span> que … (as sementes) … depois de se decomporem na terra (pela mistura com ela) tornam a brotar/são levantadas AcPlCor 2:26.—B. 1096.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφορά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφορά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">συμφέρω</span>) acontecimento infeliz (na literatura grega é um truísmo que o céu distribui tanto o bem como o mal, e um acontecimento ou evento pode, portanto, ser benéfico ou nocivo. Esta última característica [contraste <span class=\"greek\">συμφέρω</span>, <span class=\"greek\">σύμφορος</span>, em sentido positivo] passou a associar-se cada vez mais a <span class=\"greek\">ς</span>. [v. L-S-J-M s.v. <span class=\"greek\">ς</span>. II 2]) infortúnio, calamidade, desastre (assim no singular e no plural Pind., Hdt.+). Plural com <span class=\"greek\">περιπτώσεις</span> 1 Cl 1:1.—B. 1096. DELG s.v. <span class=\"greek\">φέρω</span> p. 1190. M-M s.v. <span class=\"greek\">σύμφορο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύμφορος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύμφορος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">συμφέρω</span>) benéfico, vantajoso, proveitoso (Hes., Hdt. et al.; inscrições; POxy 1676, 25 <span class=\"greek\">τὸ</span> <span class=\"greek\">σύνφορόν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ποίει</span>; 2 Macc 4:5; Just., D. 8, 1) <span class=\"greek\">τινί</span> a ou para alguém Hv 1, 3, 3; 5:5; Hs 6, 1, 3; 6, 5, 7; 7:5. Comparativo (Epict. 1, 28, 7; Jos., C. Ap. 2, 294) <span class=\"greek\">συμφορώτερόν</span> <span class=\"greek\">ἐστι</span> seguido de infinitivo Hm 6, 1, 4 (<span class=\"greek\">συμφερώτερον</span> Joly, v. seu aparato).—Substantivado <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμφορον</span> benefício, vantagem (Thu. 5, 98. O plural <span class=\"greek\">τὰ</span> <span class=\"greek\">σύμφορα</span> é mais frequente Soph. et al.) <span class=\"greek\">τό</span> <span class=\"greek\">τινος</span> <span class=\"greek\">σύμφορον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:35</a>; 10:33.—Frisk s.v. <span class=\"greek\">φέρω</span> B 3. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφορτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφορτίζω</span> sobrecarregar juntamente com, sobrecarregar <span class=\"greek\">συμφορτιζόμενος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">αὐτοῦ</span> sobrecarregado (juntamente com ele) por sua morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:10</a> variante de leitura.—DELG s.v. <span class=\"greek\">φόρτος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφύγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφύγιον</span> , <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>=<span class=\"greek\">καταφυγή</span>, o termo grego usual para ‘refúgio na fuga’ (Corpus Glossariorum Latinorum II 443, 19 <span class=\"greek\">ς</span>. confugium) lugar de refúgio, abrigo na fuga, santuário, proteção, de Jesus Cristo <span class=\"greek\">συνφύγιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅπλον</span> <span class=\"greek\">εὐδοκίας</span> refúgio/aliado e escudo de benevolência AcPl Ha 8, 23f (=BMM recto 29f; v. margem em Schubart; em lugar deste <span class=\"greek\">σύμφυτον</span> Ox 1602, 33f).—DELG s.v. <span class=\"greek\">φεύγω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφυλέτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφυλέτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φυλή</span>; inscrições greco-romanas IG XII/2, 505, 18 [II a.C.]; Doxogr. Gr. 655, 8; Rhet. Gr. VII 49, 22; Isocr. 12, 145 Bl. variante de leitura; Herodian Gramm., Philetaerus 475 [na edição de Moeris por JPierson p. 351]; Hesych.) aquele que é membro da mesma tribo ou grupo étnico, compatriota; plural, seu próprio povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>.—DELG s.v. <span class=\"greek\">φῦλον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφυρμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφυρμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">συμφύρω</span> ‘amassar juntamente’; hapax leg.—<span class=\"greek\">συμφύρομαι</span> ‘misturar-se’ Eur. et al.; Jos., Bell. 2, 150) união sexual, relação sexual (com <span class=\"greek\">ἀσέλγειαι</span>) <span class=\"greek\">συμφυρμοὶ</span> <span class=\"greek\">πονηρίας</span> atividades sexuais impróprias Hv 2, 2, 2.—DELG s.v. <span class=\"greek\">φύρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύμφυτος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύμφυτος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">φύω</span>; Pind.+; papiros, LXX, Philo; Jos., C. Ap. 1, 42, mas sobretudo = ‘inato’ ou algo semelhante; Did., Gen. 215, 11) relativo a estar associado numa experiência correlata (‘crescido juntamente’ Aristot., HA 5, 32, 557b, 18, Topica 7, 6, 145b, 3; 13) identificado com <span class=\"greek\">τινί</span> algo (Antiphon: POxy 1364, 44f) figuradamente <span class=\"greek\">σύμφυτοι</span> <span class=\"greek\">γεγόναμεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὁμοιώματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:5</a> (<span class=\"greek\">ὁμοίωμα</span> 1; cf. Dio Chrys. 11 [12], 28, de pessoas dos tempos primitivos em sua relação com o divino: <span class=\"greek\">οὐ</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θείου</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">πεφυκότες</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">συμπεφυκότες</span> <span class=\"greek\">ἐκείνῳ</span>=não [vivendo] longe do divino, mas crescendo em seu próprio meio; de fato, poder-se-ia afirmar, crescendo juntamente com ele). SStricker, D. Mysteriengedanke des hl. Pls nach Rö 6:2–11: Liturgisches Leben 1, ’34, 285–96; OKuss, D. Römerbrief I, ’63, 299f; v. também comentários de OMoe2 ’48; ANygren ’51; CCranfield ’75. Sobre Ox 1602, 33f v. <span class=\"greek\">συμφύγιον</span>.—DELG s.v. <span class=\"greek\">φύομαι</span> C. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφύω</span> 2.º aoristo passivo, particípio <span class=\"greek\">συμφυείς</span> (transitivo em Pla. et al.; intransitivo em Hippocr., Pla. et al., inclusive Wsd 13:13; Philo, Dec. 87; Jos., Bell. 6, 155, Ant. 8, 63 [<span class=\"greek\">συμφυέντες</span>]) passivo intransitivo com valor ativo crescer juntamente com algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:7</a>.—DELG s.v. <span class=\"greek\">φύομαι</span> C. M-M. s.v. <span class=\"greek\">συνφύω</span>. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφωνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφωνέω</span> futuro <span class=\"greek\">συμφωνήσω</span>; 1.º aoristo <span class=\"greek\">συνεφώνησα</span>, passivo <span class=\"greek\">συνεφωνήθην</span> (v. os três verbetes seguintes; Pla., Aristot. et al.; inscrições, papiros, LXX, Philo; Jos., Ant. 10, 106, C. Ap. 2, 181; Ath.)</p>\n<p class=\"entry-text\">① ser tão semelhante ou similar a ponto de corresponder, de coisas</p>\n<p class=\"entry-text\">ⓐ ajustar-se a, corresponder a, concordar com (Pla., Aristot. et al.; Demetr.: 722 Fgm. 2, 2 Jac. [absoluto]) com dativo <span class=\"greek\">τούτῳ</span> <span class=\"greek\">συμφωνοῦσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> com isto (isto é, com o chamado de Deus às nações) concordam as palavras dos profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:15</a> (cf. Jos., Ant. 1, 107; 15, 174). <span class=\"greek\">τῷ</span> <span class=\"greek\">παλαιῷ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">συμφωνήσει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπίβλημα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a>. (<span class=\"greek\">λίθοι</span>) <span class=\"greek\">μὴ</span> <span class=\"greek\">συμφωνοῦντες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἑτέροις</span> <span class=\"greek\">λίθοις</span> Hs 9, 6, 4.</p>\n<p class=\"entry-text\">ⓑ ajustar-se mutuamente <span class=\"greek\">συμφωνοῦσιν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁρμογαί</span> as juntas (das pedras) encaixam-se Hv 3, 5, 1c. <span class=\"greek\">συμφ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁρμογαῖς</span> <span class=\"greek\">αὐτῶν</span> elas se encaixam pelas suas juntas 3, 5, 1a. <span class=\"greek\">συμφ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁρμογαῖς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">λίθων</span> 3, 5, 2; cf. 3, 2, 6.</p>\n<p class=\"entry-text\">ⓒ concordar quanto ao som, de jarros vazios que soam em harmonia quando batem uns contra os outros <span class=\"greek\">συμφωνοῦσιν</span> <span class=\"greek\">ἀλλήλοις</span> Hm 11:13.</p>\n<p class=\"entry-text\">② ter interesses comuns, estar de acordo, em harmonia, de pessoas <span class=\"greek\">τινί</span> com alguém (Pla., Aristot. et al.; Strabo 12, 3, 25) <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">συνεφώνησαν</span> estavam de acordo uns com os outros Hv 3, 5, 1b.</p>\n<p class=\"entry-text\">③ ter chegado a um acordo acerca de algo, ter o mesmo parecer, concordar, com ênfase no resultado específico de negociações, de pessoas (Diod S 12, 25, 3; 4 Km 12:9; Jos., C. Ap. 1, 17; 2, 255 <span class=\"greek\">τινὶ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">συμφωνήσουσιν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πράγματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. Passivo impessoal <span class=\"greek\">συνεφωνήθη</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πειράσαι</span>; concordastes em pôr à prova?, literalmente ‘foi acordado por vós pôr à prova?’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:9</a> (B-D-F §202; 409, 3; cf. latim convenit inter vos; Rob. 1084). De um acordo comercial (frequentemente nos papiros) <span class=\"greek\">συμφωνήσας</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐργατῶν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δηναρίου</span> chegou a um acordo ou ajustou com os trabalhadores por um denário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:2</a> (sobre <span class=\"greek\">ἐκ</span> com genitivo de preço v. <span class=\"greek\">ἐκ</span> 4b). Semelhantemente <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">δηναρίου</span> (genitivo de preço) <span class=\"greek\">συνεφώνησάς</span> <span class=\"greek\">μοι</span>; v. 13, mas esta última passagem também pode enquadrar-se em 2.—DELG s.v. <span class=\"greek\">φωνή</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφώνησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφώνησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">συμφωνέω</span>; An. Ox. IV 326, 12) estado de interesses compartilhados, acordo <span class=\"greek\">τινὸς</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> de alguém com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:15</a>.—DELG s.v. <span class=\"greek\">φωνή</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμφωνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμφωνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">σύμφωνος</span>; Pla. et al.; papiros, LXX; EpArist 302; Philo; Jos., C. Ap. 2, 170; 179; Tat. 12, 3) em nossa literatura somente numa passagem, como termo relativo à música <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:25</a>. É interpretado de diversas maneiras:</p>\n<p class=\"entry-text\">① som produzido por vários instrumentos, música (Paradoxogr. Flor. 43).</p>\n<p class=\"entry-text\">② grupo de músicos executantes, banda, orquestra (PFlor 74, 5; 18; POxy 1275, 9; 12; 24 <span class=\"greek\">συμφωνία</span> <span class=\"greek\">αὐλητῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μουσικῶν</span>).</p>\n<p class=\"entry-text\">③ instrumento de sopro (Polyb. 26, 1, 4 <span class=\"greek\">μετὰ</span> <span class=\"greek\">κερατίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">συμφωνίας</span>; Athen. 13, 594e <span class=\"greek\">χορῷ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παντοίοις</span> <span class=\"greek\">ὀργάνοις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">συμφωνίαις</span>; Da 3:5, 15 variante de leitura. Empréstimo nos escritos rabínicos com o significado de ‘flauta dupla’ [Billerb. IV 396, 400]). Segundo PBarry, JBL 23, 1904, 180ff; 27, 1908, 99ff, uma espécie de gaita de foles. Contra isso GMoore, JBL 24, 1905, 166ff. PSchmitt-Pantel, La cité au banquet, histoire des repas publics dans les cités grecques ’92 (v. SEG XLII, 1746 sobre o vocabulário dos banquetes).—DELG s.v. <span class=\"greek\">φωνή</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύμφωνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύμφωνος</span>, <span class=\"greek\">ον</span> (v. <span class=\"greek\">συμφωνία</span>; hinos homéricos, Pla. et al.; inscrições, papiros, 4 Macc; Ar. 13, 5; Tat. 25, 2; Ath.; advérbio <span class=\"greek\">συμφώνως</span> Ath., R. 23 p. 77, 4)</p>\n<p class=\"entry-text\">① relativo a estar em consonância com, afinado com, harmonioso, em linguagem figurada IEph 4:1, 2; 5:1.</p>\n<p class=\"entry-text\">② relativo a estar de acordo, concordante (EpArist 302; Jos., C. Ap. 2, 169, Ant. 15, 408); substantivado <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμφωνον</span> acordo (Philo): <span class=\"greek\">ἐκ</span> <span class=\"greek\">συμφώνου</span> de comum acordo (PLond II, 334, 19 p. 211 [166 d.C.]; PHamb 15, 8; PStras 14, 13; BGU 446, 13 e outras ocorrências nos papiros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>.—M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμψέλιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμψέλιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (POxy 921; Sb 4292, 4. Escrito <span class=\"greek\">συμψέλλιον</span> em todo o códice A de Hermas [v. nota de Joly Hv 3, 1, 4 aparato]; assim também AcThom 49 [Aa II/2, 165, 19]; <span class=\"greek\">σεμψέλλιον</span>: PGrenf II, 111, 37; CWessely, WienerStud 24, 1902, 99f. Empréstimo latino = subsellium. Empréstimo nos escritos rabínicos) banco Hv 3, 1, 4; 7; 3, 2, 4; 3, 10, 1; 5; 3, 13, 3; m 11:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμψηφίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμψηφίζω</span> (como médio Aristoph., X. et al.) em nossa literatura ativo (como PGM 13, 348) 1.º aoristo <span class=\"greek\">συνεψήφισα</span> calcular um total, somar, computar <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὰς</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">αὐτῶν</span> o preço deles (=os livros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:19</a>. V. também <span class=\"greek\">συνοψίζω</span>.—<span class=\"greek\">τὴν</span> <span class=\"greek\">ποσότητα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δαπάνης</span> somar o montante da despesa Hs 5, 3, 7 variante de leitura. <span class=\"greek\">τὰς</span> <span class=\"greek\">ὥρας</span> contar as horas v 3, 1, 4 variante de leitura.—O passivo (cf. Appian, Bell. Civ. 3, 22 §83; Sb 7378, 9 [II d.C.]; Jer 30:14 variante de leitura) <span class=\"greek\">συνεψηφίσθη</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀποστόλων</span> foi contado como um dos apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:26</a> D (em lugar de <span class=\"greek\">συγκατεψηφίσθη</span>). (Verbos compostos com <span class=\"greek\">σύν</span> são frequentemente empregados com <span class=\"greek\">μετά</span> na LXX: Johannessohn, Präp. 205.)—DELG s.v. <span class=\"greek\">ψῆφος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύμψυχος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύμψυχος</span>, <span class=\"greek\">ον</span> literalmente ‘unido em espírito’, harmonioso (assim em Polemo, Decl. 2, 54 p. 34, 19) com <span class=\"greek\">τὸ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">φρονῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:2</a> (mas AFridrichsen, PhilolWoch 58, ’38, 910–12 de todo o coração).—DELG s.v. <span class=\"greek\">ψυχή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύν</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύν</span> (a coiné desconhece inteiramente a forma ática <span class=\"greek\">ξύν</span>; B-D-F §34, 4; Rob. 626) preposição com dativo (Hom.+.—Para a bibliografia v. <span class=\"greek\">ἀνά</span> e <span class=\"greek\">μετά</span>, início; Tycho Mommsen, Beiträge zu der Lehre v. den griech. Präp. 1895, especialmente p. 395ff; B-D-F 221; Rob. 626–28) com (é arriscado tentar estabelecer diferenças sutis no emprego de <span class=\"greek\">σύν</span> e <span class=\"greek\">μετά</span> no que se refere à associação, pois o NT manifesta um emprego bastante fluido).</p>\n<p class=\"entry-text\">① com dativo de pessoa, marcador de acompanhamento e associação</p>\n<p class=\"entry-text\">ⓐ com ênfase no aspecto associativo</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. estar, permanecer, estar de pé etc., com alguém <span class=\"greek\">ἀνακεῖσθαι</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:2</a>. <span class=\"greek\">διατρίβειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:28</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἑστῶτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:14</a>. <span class=\"greek\">μένειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>; 24:29 (aqui alternando com <span class=\"greek\">μένειν</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> como seu equivalente).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. ir, viajar etc. com alguém <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> ir com, acompanhar alguém (Jos., Vi. 65 Just., D. 78, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:12</a>; vir com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:4</a>. <span class=\"greek\">ἀπέρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:26</a>. <span class=\"greek\">εἰσέρχεσθαι</span> (X., Cyr. 3, 3, 13; JosAs 22:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:8</a>. <span class=\"greek\">ἐξέρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:23</a>; 14:20; AcPl Ant 13, 3 (=Aa I 236, 6). <span class=\"greek\">συνέρχεσθαι</span> 21:16. <span class=\"greek\">πορεύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:20</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. No caso de <span class=\"greek\">εἶναι</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> a ênfase recai às vezes puramente sobre o estar junto (Tat. 5, 1 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">δύναμις</span> …), e às vezes sobre o acompanhamento: estar com alguém (X., An. 1, 8, 26; grafito alexandrino, provavelmente da época imperial [Dssm., LO 257, 4=LAE 303, 1] <span class=\"greek\">εὔχομαι</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τάχυ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">εἶναι</span> [dirigido a uma pessoa falecida]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a> (<span class=\"greek\">ἔτι</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ὑμῖν</span> como 4 Macc 18:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:23</a> (Quint. Smyrn. 7, 698, de Aquiles <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἀθανάτοισι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a>; com indicação de lugar <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄρει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:18</a>. Acompanhar, seguir alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a>. Ser companheiro ou discípulo de alguém 8:38; 22:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:13</a>; estar entre os assistentes de alguém 13:7. <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ἰουδαίοις</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀποστόλοις</span> 14:4 (cf. X., Cyr. 7, 5, 77). <span class=\"greek\">οἱ</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὄντες</span> camaradas, companheiros, assistentes de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:9</a>. Sem <span class=\"greek\">ὄντες</span> (X., An. 2, 2, 1; UPZ 160, 9 [119 a.C.]; Jos., Vi. 196, Ant. 11, 105; 12, 393; Just., D. 9, 3 e outras ocorrências) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:9</a>; 8:45 variante de leitura; 9:32; 24:10 (<span class=\"greek\">αἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐταῖς</span>); 24:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:17</a>. No singular <span class=\"greek\">Τίτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἐμοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:3</a>.—Com um substantivo (ParJer 7:9 <span class=\"greek\">τοῖς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">δεσμίοις</span>; POxy 242, 33; BGU 1028, 19) <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τεχνῖται</span> seus colegas artesãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:38</a>. <span class=\"greek\">Στεφανᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πρεσβύτεροι</span> AcPlCor 1, 1. <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἀδελφοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:21</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πιστοί</span> MPol 12:3.</p>\n<p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> juntar-se a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:13</a> (<span class=\"greek\">γίνομαι</span> 6f). <span class=\"greek\">καθίσαι</span> <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> sentar-se ao lado de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a>.</p>\n<p class=\"entry-text\">ⓑ com ênfase na associação em uma atividade</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. fazer: <span class=\"greek\">Ἁνανίας</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">Σαπφίρῃ</span> <span class=\"greek\">ἐπώλησεν</span> <span class=\"greek\">κτῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:1</a>. <span class=\"greek\">ἐπίστευσεν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">αὐτοῦ</span> 18:8. <span class=\"greek\">προσεύχεσθαι</span> 20:36. <span class=\"greek\">ἁγνίσθητι</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτοῖς</span> 21:24.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:22</a>.—Ter empatia: <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμὴν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">ἱλαρὸς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τούτοις</span> e o pastor participou da alegria do anjo por estes (estacas que davam fruto) Hs 8, 1, 18 (cf. TestAbr B 6 p. 110, 2 [Stone 68] <span class=\"greek\">ἔκλαυσεν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">υἰῷ</span> <span class=\"greek\">αὐτου</span>; TestJob 53:1)</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. experimentar, sofrer: <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ἀποθανεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:35</a>. <span class=\"greek\">ἀναιρεθῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:32</a>. <span class=\"greek\">σταυρωθῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:38</a>; cf. v. 44. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:32</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">εὐλογοῦνται</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πιστῷ</span> <span class=\"greek\">Ἀβραάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:9</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κέκρυπται</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:3</a>.—Em união mística com Cristo, o cristão chega a <span class=\"greek\">ἀποθανεῖν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">Χριστῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:20</a> e a <span class=\"greek\">ζῆν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:10</a> (ELohmeyer, <span class=\"greek\">Σὺν</span> <span class=\"greek\">Χριστῷ</span>: Deissmann Festschr. 1927, 218–57; JDupont, <span class=\"greek\">Σὺν</span> <span class=\"greek\">Χριστῷ</span> ’52).</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. Ao acusativo de objeto pessoal do verbo na voz ativa, <span class=\"greek\">σύν</span> acrescenta outras pessoas que passam pela mesma experiência ao mesmo tempo com, assim como (Philochorus [IV/III a.C.]: 328 Fgm. 7a Jac. <span class=\"greek\">ὥπλιζε</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἄρρεσι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θηλείας</span>) <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">σταυροῦσιν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">λῃστάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:27</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βεβαιῶν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:21</a>. <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐγερεῖ</span> 4:14; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:14</a>.</p>\n<p class=\"entry-text\">② marcador de auxílio (X., Cyr. 5, 4, 37 <span class=\"greek\">ἢν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὦσιν</span>, An. 3, 1, 21; Jos., Ant. 11, 259 <span class=\"greek\">θεὸς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἐμοί</span> a graça de Deus, que veio em meu auxílio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:10</a>. (A expressão <span class=\"greek\">σὺν</span> <span class=\"greek\">θεῷ</span>: PGrenf II, 73, 16 <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἔλθῃ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">θεῷ</span>; POxy 1220, 23 et al.; Pind., O. 10, 105 [115] <span class=\"greek\">σὺν</span> <span class=\"greek\">Κυπρογενεῖ</span> ‘com o favor de Afrodite’ não é semanticamente paralela; v. BRees, JEA 36, ’50, 94f).</p>\n<p class=\"entry-text\">③ marcador de ligação, com ênfase no acréscimo de uma pessoa ou coisa</p>\n<p class=\"entry-text\">ⓐ com, ao mesmo tempo que</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τόκῳ</span> meu dinheiro com juros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:27</a> (POsl 40, 7 [150 d.C.] <span class=\"greek\">κεφάλαιον</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τόκοις</span>). <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κλινιδίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:19</a>. <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a>. <span class=\"greek\">σύν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πειρασμῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔκβασιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. às vezes <span class=\"greek\">σύν</span> é quase equivalente a <span class=\"greek\">καί</span> (O. Wilck 1535, 5 [II a.C.] <span class=\"greek\">τοῖς</span> <span class=\"greek\">συνστρατιώταις</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">Πλάτωνι</span>; Johannessohn, Präp. 207; AssMos Fgm. f Denis p. 65 <span class=\"greek\">Ἰησοῦς</span> … <span class=\"greek\">σὺν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Χαλέβ</span>) (juntamente) com <span class=\"greek\">οἱ</span> <span class=\"greek\">γραμματεῖς</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρεσβυτέροις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:1</a>. <span class=\"greek\">Πέτρος</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰωάννῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:14</a>; 10:2; 14:5; 23:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:1</a> (cf. POxy 1293, 3 [117–38 d.C.]); 1 Cl 65:1; IPol 8:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">παθήμασιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:24</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a>.</p>\n<p class=\"entry-text\">ⓑ quando se introduz um novo fator, além de, em acréscimo a (Jos., Ant. 17, 171) <span class=\"greek\">σὺν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">τούτοις</span> além de tudo isto, em acréscimo a ou à parte de tudo isto (cf. <span class=\"greek\">σὺν</span> <span class=\"greek\">τούτοις</span>=‘à parte disto’: Galen, CMG V 9, 1 p. 381, 2; 3 Macc 1:22; JosAs 11 códice A [p. 53, 17 Bat.]; GrBar 16:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:21</a>.</p>\n<p class=\"entry-text\">ⓒ em combinação com <span class=\"greek\">ἅμα</span> (v. esse verbete 2b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:17</a>; 5:10.—BMcGrath, CBQ 14, ’52, 219–26: ‘Syn’-Words in Paul; OGert, D. mit. syn-verbundenen Formulierungen in paul. Schrifttum, diss. Berlin, ’52.—M-M. DELG. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνάγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συνάγω</span> futuro <span class=\"greek\">συνάξω</span>; 1.º aoristo <span class=\"greek\">συνῆξα</span> (2 Esdr 7:28; 8:15; cf. ParJer 7:16f; D 10:5), infinitivo <span class=\"greek\">συνάξαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:17</a> variante de leitura (sobre a forma tardia do aoristo v. Schwyzer I 749, 1; JMoulton, Cambridge Bibl. Essays 1909, 485f); 2.º aoristo <span class=\"greek\">συνήγαγον</span>. Passivo: 1.º futuro <span class=\"greek\">συναχθήσομαι</span>; 1.º aoristo <span class=\"greek\">συνήχθην</span>; perfeito, 3.ª pessoa do singular <span class=\"greek\">συνῆκται</span> LXX (Hom. et al.)</p>\n<p class=\"entry-text\">① fazer que venham a estar juntas, reunir, recolher</p>\n<p class=\"entry-text\">ⓐ coisas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:6</a>. <span class=\"greek\">κλάσματα</span> 6:12f. <span class=\"greek\">ξύλα</span> MPol 13:1. De peixes de toda espécie, que a rede recolhe quando é lançada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:47</a>. Dos fragmentos de um manuscrito que se está deteriorando MPol 22:3a; EpilMosq 5a. De produtos do campo (Ex 23:10; Lev 25:3; JosAs 1:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>, 26; cf. passivo (Jos., Ant. 5, 242) D 9:4a. Com indicação do destino <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (Diod S 19, 100, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">ἄσφαλτον</span> <span class=\"greek\">ς</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τόπον</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀποθήκην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:12</a>; 6:26; 13:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:17</a>. <span class=\"greek\">ποῦ</span> 12:17. <span class=\"greek\">ἐκεῖ</span> v. 18. <span class=\"greek\">συνάγειν</span> <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:13</a> reunir tudo, talvez com uma conotação comercial, converter tudo em dinheiro (cf. Plut., Cato Min. 762 [6, 7] <span class=\"greek\">κληρονομίαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀργύριον</span> <span class=\"greek\">συναγαγών</span>).—Em linguagem figurada <span class=\"greek\">συνάγειν</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> unir-se a alguém na reunião (oposto a <span class=\"greek\">σκορπίζω</span>, v. esse verbete 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:23</a>. <span class=\"greek\">συνάγειν</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a>. De ovelhas, metaforicamente 10:16 P66.</p>\n<p class=\"entry-text\">ⓑ de pessoas, trazer ou convocar para junto, reunir certo número de pessoas (1 Km 5:11; PsSol 11:3; TestJob 17:2; Jos., C. Ap. 1, 234; IAndrosIsis, Kyme 17 marido e mulher) <span class=\"greek\">πάντας</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">εὗρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a>. <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρχιερεῖς</span> 2:4 (Appian, Bell. Civ. 4, 4 §15: em vista de sinais assustadores <span class=\"greek\">ἡ</span> <span class=\"greek\">βουλὴ</span> <span class=\"greek\">μάντεις</span> <span class=\"greek\">συνῆγεν</span>). <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> 2 Cl 17:4; (Is 66:18). <span class=\"greek\">συνέδριον</span> (Diod S 17, 4, 2 <span class=\"greek\">συνέδριον</span> <span class=\"greek\">συναγαγών</span>, igualmente 17, 30, 1.—Cf. Ex 3:16 <span class=\"greek\">τ</span>. <span class=\"greek\">γερουσίαν</span>, igualmente Jos., Ant. 5, 332; PsSol 8:28 <span class=\"greek\">τὴν</span> <span class=\"greek\">διασπορὰν</span> <span class=\"greek\">Ἰσραήλ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:47</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> (Diod S 4, 53, 1 <span class=\"greek\">συναγαγεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πλήθη</span>; Jos., Ant. 3, 188; cf. ParJer 7:16f <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:30</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> (Aeneas Tact. 431; Lucian, Jupp. Trag. 15) 14:27; cf. D 10:5. <span class=\"greek\">συνάξεις</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">σοὺς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στέγος</span> <span class=\"greek\">σου</span> 1 Cl 12:6. Seguido de <span class=\"greek\">εἰς</span> para indicar o lugar (X., Ages. 1, 25; Jos., Vi. 280 <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">προσευχήν</span>; ApcEsdr 3:6 <span class=\"greek\">πάντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κοιλάδα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰωσαφάτ</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:16</a> (Diod S 17, 20, 1 <span class=\"greek\">συνήγαγεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρίστους</span>; 13, 49, 3). <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:52</a> (cf. <span class=\"greek\">εἰς</span> 4a). Para indicar finalidade (Dionys. Hal. 2, 45 <span class=\"greek\">ὅπως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φιλίαν</span> <span class=\"greek\">συνάξουσι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>; Jos., C. Ap. 1, 111) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πόλεμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:14</a>; 20:8. Cf. 13:10 variante de leitura. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:27</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">κἀμὲ</span> <span class=\"greek\">συναγάγῃ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκλεκτῶν</span> para que o Senhor Jesus Cristo me reúna também com os eleitos MPol 22:3b; EpilMosq 5b.—Passivo, seja em sentido passivo, ser reunido ou congregado <span class=\"greek\">συναχθήσονται</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:32</a>. <span class=\"greek\">συναχθήτω</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">περάτων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σὴν</span> <span class=\"greek\">βασιλείαν</span> D 9:4b; ou com valor ativo, reunir-se, juntar-se, congregar-se (Gen 29:8; Dt 33:5; Esth 9:18; En 13:9; TestReub 1:2; ApcMos 5:38; ViJer 12 [p. 73, 8 Sch.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:41</a>; 27:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>; MPol 18:2; D 14:1; 16:2. O sujeito pode também ser uma palavra coletiva <span class=\"greek\">συνήχθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρεσβυτέριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:66</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:44</a>. Mais precisamente determinado: quanto ao lugar <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:5</a> variante de leitura. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεῖπνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:17</a>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:5</a>, 31. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> com a congregação 11:26. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἦτε</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">συνηγμένοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόλπῳ</span> <span class=\"greek\">μου</span> se estiverdes reunidos comigo em meu seio 2 Cl 4:5 (um dito do Senhor, de origem desconhecida). <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span> com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:18</a> D. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> para junto de alguém ou com alguém (TestBenj10:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:2</a>; 27:62; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1</a>; 6:30; 7:1. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> GPt 8:28. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> com alguém ou ao redor de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:21</a>; contra alguém (Gen 34:30; Josh 10:6; Hos 10:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:27</a> (=<span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> v. 26 segundo Ps 2:2). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζωήν</span> para a vida 2 Cl 17:3. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> (v. <span class=\"greek\">αὐτός</span> 3b e <span class=\"greek\">ἐπί</span> 1c<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:26</a> (Ps 2:2); 1 Cl 34:7. <span class=\"greek\">συναχθέντες</span> <span class=\"greek\">ὁμοῦ</span> GJs 9:1. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> (Mi 2:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:4</a>. <span class=\"greek\">συναχθέντες</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρεσβυτέρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:12</a>; também de uma pessoa individual <span class=\"greek\">συνήχθη</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:2</a> (HReynen, BZ 5, ’61, 86–90 ‘permanecer’). Com um advérbio de lugar <span class=\"greek\">οὗ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:8</a>; <span class=\"greek\">ὅπου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a> variante de leitura; <span class=\"greek\">ἐκεῖ</span> (TestBenj 9:2; Jos., Ant. 6, 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:37</a> variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:2</a>. Seguido de infinitivo de finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:44</a>; 15:6; 20:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:19</a>.</p>\n<p class=\"entry-text\">② efetuar o restabelecimento de relações, aproximar, reconciliar, extensão de 1 (Demosth. et al.; Herodian 3, 13, 5; 4, 3, 4; 9) <span class=\"greek\">μαχομένους</span> <span class=\"greek\">συναγαγών</span> B 19:12.</p>\n<p class=\"entry-text\">③ reunir com, conduzir ou trazer (para junto de) (Hom. et al.) passivo <span class=\"greek\">πᾶσα</span> <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">συνήχθη</span>, do cristianismo como o único caminho para Deus para todos IMg 10:3 (a preposição provavelmente funciona aqui em sentido associativo).</p>\n<p class=\"entry-text\">④ dar acolhida a, convidar/receber como hóspede (com <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> ou <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> acrescentado Judg 19:18; 2 Km 11:27; Dt 22:2. V. também Gen 29:22; Achilles Tat. 3, 8, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:35</a>, 38, 43.</p>\n<p class=\"entry-text\">⑤ intransitivo (assim, mas com significado diferente, Theocr. 22, 82; Polyb. 11, 18, 4 [ambos = encontrar-se de maneira hostil]) deslocar-se para outra posição, avançar, mover-se (Aelian, VH 3, 9 <span class=\"greek\">συνάγοντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πολέμου</span>) <span class=\"greek\">σύναγε</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἄνω</span> sobe mais acima <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> D (a preposição pode funcionar aqui em sentido deferente e associativo ‘vem mais para cima’).—Sobre Dg 12:9 v. <span class=\"greek\">καιρός</span>, fim (cf. Jos., C. Ap. 1, 126 <span class=\"greek\">συνάγεται</span> <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συναγωγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συναγωγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Thu. et al.; inscrições, papiros, LXX, Just.). O termo <span class=\"greek\">ς</span>. é fluido, e seu emprego como empréstimo no inglês em conexão com o culto sugere um uso técnico que não faz justiça à extraordinária amplitude de emprego de <span class=\"greek\">ς</span>. Originalmente em sentido ativo ‘ato de reunir, congregar’, depois na LXX e em documentos contemporâneos ‘reunião’ ou ‘lugar de reunião’.—Para evidências epigráficas relativas ao uso cultual v. ROster, NTS 39, ’93, 181 n. 14 (os principais corpora); para sinônimos, p. 186; cf. New Docs 4, 202f.</p>\n<p class=\"entry-text\">① lugar onde algo se reúne, lugar de reunião, das bacias em que a água é reunida na criação (Gen 1:9; cf. Jos., Ant. 15, 346 <span class=\"greek\">ς</span>. <span class=\"greek\">ὑδάτων</span>; Did., Gen. 25, 14 <span class=\"greek\">ς</span>., <span class=\"greek\">ἣν</span> <span class=\"greek\">καλεῖν</span> <span class=\"greek\">εἰώθασιν</span> <span class=\"greek\">ὠκεανόν</span>) 1 Cl 20:6.</p>\n<p class=\"entry-text\">② lugar de assembleia (inscrição de Cibele [Bilderatlas z. Religionsgesch. 9–11, 1926 p. xix n.º 154] <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">συναγωγῇ</span>; v. New Docs 3, 43. Sb 4981, 6f [restaurado].—Sobre <span class=\"greek\">συναγωγή</span> como sala de reuniões cf. <span class=\"greek\">συνέδρια</span>, das casas de reunião dos pitagóricos Polyb. 2, 39, 1).</p>\n<p class=\"entry-text\">ⓐ da sinagoga judaica (é empregado para um lugar de reunião dos judeus em Philo, Omn. Prob. Lib. 81 [com referência aos essênios]; Jos., Bell. 2, 285; 289; 7, 44, Ant. 19, 300; 305; CIG 9894; 9904; BCH 21, 1897 p. 47; <span class=\"greek\">Συναγωγὴ</span> <span class=\"greek\">Ἑβραίων</span> em Corinto [v. <span class=\"greek\">Κόρινθος</span>, fim], em Roma [CIG IV, 9909] e ILydiaKP III, 42 p. 32ff.—V. AvHarnack, Mission4 II 1924, p. 568, 2; GKittel, TLZ 69, ’44, 11f.—Orig., C. Cels. 6, 23, 3; Hippol., Ref. 9, 12, 7); as pessoas vinham à <span class=\"greek\">συν</span>. para adorar a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>; 6:2, 5; 9:35; 12:9; 13:54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:39</a>; 3:1; 6:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:15</a>; 6:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:20</a>. Nos mesmos edifícios também se realizavam julgamentos e se infligiam castigos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:17</a>; 23:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:11</a>; 21:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:19</a>; 26:11 (HKee, NTS 36, ’90, 1–24, entende que Atos projeta uma situação posterior a 70 na carreira de Paulo; réplica ROster, ibid. 39, ’93, 178–208, com advertência contra a confiança na mera transliteração de <span class=\"greek\">ς</span>. e com a conclusão de que Lucas não é culpado de anacronismo; resposta de Kee, ibid. 40, ’94, 281–83 [também 41, ’95, 481–500], com a observação de que a inscrição da sinagoga de Teódoto em Jerusalém [v. Dssm. LO 378–80=LAE 439–41; Boffo, Iscrizioni n.º 31] pode perfeitamente não ser anterior ao IV d.C.; para uma crítica das opiniões de Kee v. também ESanders, Jewish Law from Jesus to the Mishnah, ’87, 341–43 notas 28 e 29. Para o emprego antigo em referência a uma sinagoga judaica, v. New Docs 4, 202, IBerenike 16, 5 [55 d.C.] de um edifício, na linha 3, de membros que nele se reúnem). Mencionam-se também sinagogas existentes em Antioquia da Pisídia 13:14; Atenas 17:17; Bereia v. 10; Damasco 9:20; Éfeso 18:19 (GHorsley, The Inscriptions of Ephesus and the NT: NovT 34, ’92, 105–68); Cafarnaum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:33</a>; 7:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:59</a> (HKohl e CWatzinger, Antike Synagogen in Galiläa 1916; HVincent, RB 30, 1921, 438ff; 532ff; GOrfali, Capharnaum et ses ruines 1922); Corinto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:4</a> (v. New Docs 3, 121); Éfeso 19:8; Nazaré <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:16</a>; Salamina na ilha de Chipre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:5</a>; Tessalônica 17:1.—ESukenik, Ancient Synagogues in Palestine and Greece ’34.—Sobre a construção de sinagogas por patronos v. TRajak, Benefactors in the Greco-Jewish Diaspora, in MHengel Festschr. I ’96, 307 n. 7 bibliografia.—Sobre a relação entre <span class=\"greek\">συναγωγή</span> e <span class=\"greek\">προσευχή</span> (v. esse verbete 2) v. SKrauss, Synagogale Altertümer 1922, 11; Boffo, Iscrizioni 39–46; Pauly-W. 2.ª série IV ’32, 1284–1316; ERivkin, AHSilver Festschr. ’63, 350–54.—AGroenman, De Oorsprong der Joodsche Synagoge: NThT 8, 1919, 43–87; 137–88; HStrack, RE XIX 221–26; Elbogen2 444ff; 571ff; Billerb. IV, 115–52 (a sinagoga como instituição), 153–88 (os cultos da sinagoga); GDalman, Jesus-Jeshua (trad. PLevertoff) 1929, 38–55; SSafrai, MStern et al., The Jewish People in the 1st Century II, ’77, 908–44; LLevine, The Second Temple Synagogue, The Formative Years: The Synagogue in Late Antiquity ’87, 7–31; Schürer II 423–63; III 138–49; v. também a bibliografia citada acima por Oster, Kee e Boffo.</p>\n<p class=\"entry-text\">ⓑ também se pode entender um lugar de reunião dos judeu-cristãos (nazarenos) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:2</a> (assim LRost, PJ 29, ’33, 53–66, especialmente 54f, mas v. 4 abaixo). <span class=\"greek\">εἰς</span> <span class=\"greek\">ς</span>. <span class=\"greek\">πλήρη</span> <span class=\"greek\">ἀνδρῶν</span> Hm 11:14 (cf. a inscrição acima da entrada de um lugar de reunião marcionita perto de Damasco <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">Μαρκιωνιστῶν</span> [OGI 608, 1 de 318/19 d.C.]; Harnack, SBBerlAK 1915, 754ff). V. 5 abaixo.</p>\n<p class=\"entry-text\">③ os membros de uma sinagoga, (a congregação de uma) sinagoga (Just., D. 53, 4 e outras ocorrências; referências para este emprego em Schürer II 423f; III 81–86; EPeterson, Byz.-Neugriech. Jahrbücher 2, 1921, 208)</p>\n<p class=\"entry-text\">ⓐ de sinagogas localizadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:9</a> (Schürer II 428; cf. CIJ 683 [=Corpus Ins. Regni Bosporani ’65 n.º 70], para tradução e ilustração v. RMackennan, Bar 22/2, ’96, 47); 9:2.</p>\n<p class=\"entry-text\">ⓑ em sentido restrito, daqueles que se consideram <span class=\"greek\">Ἰουδαῖοι</span> mas são hostis aos cristãos (que também se identificam como <span class=\"greek\">Ἰουδαῖοι</span>, sejam israelitas por descendência ou crentes provenientes das nações—sobre a composição mista dos seguidores de Jesus Cristo v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a>; ISm 1:2), e são chamados (em vez de <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">κυρίου</span>: Num 16:3; 20:4; 27:17; Josh 22:16; Ps 73:2) <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> sinagoga de Satanás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:9</a>; 3:9 (cf. Just., D. 104, 1 <span class=\"greek\">ἡ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πονηρευομένων</span>; v. 5 abaixo).</p>\n<p class=\"entry-text\">④ reunião sinagogal, reunião, assembleia para o culto, dos judeanos <span class=\"greek\">λυθείσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συναγωγῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a> (v. <span class=\"greek\">λύω</span> 3).—Transferido para reuniões de congregações judeu-cristãs (cf. TestBenj 11:2, 3; Just., D. 63, 5; 124, 1; Theoph. Ant. 2, 14 [p. 136, 12]) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">εἰσέλθῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">συναγωγὴν</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:2</a> (esta é a interpretação preferida: HermvSoden, Ropes, Meinertz, FHauck; v. 2b acima). <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">δικαίων</span> Hm 11:9, 13, cf. 14. <span class=\"greek\">πυκνότερον</span> <span class=\"greek\">συναγωγαὶ</span> <span class=\"greek\">γινέσθωσαν</span> as reuniões (da congregação) devem realizar-se mais frequentemente IPol 4:2. (<span class=\"greek\">συναγ</span>. também se encontra fora dos círculos judaicos e cristãos para reuniões periódicas; v. os exemplos em MDibelius, Jakobus 1921 p. 124, 1. Também Philo Bybl.: 790 Fgm. 4, 52 Jac. [em Eus., PE 1, 10, 52] <span class=\"greek\">Ζωροάστρης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἱερᾷ</span> <span class=\"greek\">συναγωγῇ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Περσικῶν</span> <span class=\"greek\">φησι</span>; OGI 737, 1 [II a.C.] <span class=\"greek\">ς</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀπολλωνείῳ</span>; PLond 2710 recto, 12: HTR 29, ’36, 40; 51.—Sb 8267, 3 [5 a.C.] inscrição honorífica de uma <span class=\"greek\">ς</span>. politeísta=associação. Com referência ao culto imperial BGU 1137, 2 [6 a.C.]. Sobre o emprego cristão da palavra v. também ADeissmann, Die Urgeschichte des Christentums im Lichte der Sprachforschung 1910, 35f).</p>\n<p class=\"entry-text\">⑤ grupo de pessoas que se associam, frequentemente com intenção hostil, bando, quadrilha <span class=\"greek\">ς</span>. <span class=\"greek\">πονηρευομένων</span> (Ps 21:17) B 5:13; 6:6; GJs 15:1 variante de leitura (em lugar de <span class=\"greek\">σύνοδος</span>).—SSafrai, The Synagogue: CRINT I/2, 908–44; WSchrage, BHHW III 1906–10; Kl. Pauly V 451f.—V. <span class=\"greek\">ἀρχισυναγωγός</span> e New Docs 4, 213–20. DELG s.v. <span class=\"greek\">ἄγω</span>. EDNT. DLNT 1141–46. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0340-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συναγωνίζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συναγωνίζομαι</span> médio depoente; 1.º aoristo <span class=\"greek\">συνηγωνισάμην</span> (Thu. et al.; inscrições; TestAsh 6:2; JosAs 23:4 [códice A p. 74, 8 Bat. e Pal. 364 em lugar de <span class=\"greek\">συνάρασθε</span>]) unir-se a alguém num esforço comum, lutar/contender juntamente com <span class=\"greek\">τινί</span> alguém, com ênfase numa função de apoio, ajudar, auxiliar (Demosth. 21, 190; SIG 651, 14 <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρεσβευταῖς</span> <span class=\"greek\">συναγωνιζόμενος</span> <span class=\"greek\">ἐκτενῶς</span>; ZPE 35, ’79 n.º 42, de um benfeitor; Philo, Spec. Leg. 4, 179; Jos., Ant. 12, 18; 17, 220; Tat. 19, 2; Hippol., Ref. 7, 31, 5; substantivo em POxy 1676, 36f [III d.C.]: ‘colaborador’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:30</a> (aqui talvez com conotações judiciais: um apelo comum a Deus diante da oposição ao apóstolo).—DELG s.v. <span class=\"greek\">ἄγω</span>. M-M.</p></section></article>"};
